            float num = 0, den = 0;
            for (int i = 0; i < b.N; i++) { float d = Ax[i] - b[i]; num += d * d; den += b[i] * b[i]; }
            return math.sqrt(num) / math.sqrt(math.max(den, (float)1e-30));
